// The surface lock (spec 0016, F1): `tools.lock.json` names every tool and holds the SHA-256 of what a client sees of
// it (title, description, input and output schemas, the four hints), and one digest of all of them in order. A tool, a
// hint or a schema cannot change without this file changing, and the file is regenerated by the same command as the
// client files, so a change to the surface is a visible line in a diff.
import { contractVersion } from "@tsukuri/lifecycle";
import { sha256Hex } from "@tsukuri/pipeline";
import { Array as Arr, Effect, Formatter } from "effect";

/** What a client sees of a tool, in a fixed field order. */
export interface ToolView {
  readonly annotations?:
    | {
        readonly destructiveHint?: boolean | undefined;
        readonly idempotentHint?: boolean | undefined;
        readonly openWorldHint?: boolean | undefined;
        readonly readOnlyHint?: boolean | undefined;
        readonly title?: string | undefined;
      }
    | undefined;
  readonly description?: string | undefined;
  readonly inputSchema: unknown;
  readonly name: string;
  readonly outputSchema?: unknown;
  readonly title?: string | undefined;
}

/** The facts the lock covers, with the hints always present and the order of keys fixed. */
const toolFacts = (tool: ToolView) => ({
  annotations: {
    destructiveHint: tool.annotations?.destructiveHint,
    idempotentHint: tool.annotations?.idempotentHint,
    openWorldHint: tool.annotations?.openWorldHint,
    readOnlyHint: tool.annotations?.readOnlyHint,
  },
  description: tool.description,
  inputSchema: tool.inputSchema,
  name: tool.name,
  outputSchema: tool.outputSchema,
  title: tool.title ?? tool.annotations?.title,
});

const digestOfText = (text: string) =>
  sha256Hex(new TextEncoder().encode(text));

export interface Lock {
  readonly contract: string;
  readonly digest: string;
  readonly tools: readonly { readonly digest: string; readonly name: string }[];
}

/** The lock of `tools`, in the order given. */
export const lockOf = Effect.fnUntraced(function* lockOf(
  tools: readonly ToolView[]
) {
  const rows = yield* Effect.forEach(tools, (tool) =>
    Effect.map(
      digestOfText(Formatter.formatJson(toolFacts(tool))),
      (digest) => ({
        digest,
        name: tool.name,
      })
    )
  );

  return {
    contract: contractVersion,
    digest: yield* digestOfText(
      Formatter.formatJson(Arr.map(rows, (row) => [row.name, row.digest]))
    ),
    tools: rows,
  } satisfies Lock;
});

/** The text of `tools.lock.json`. */
export const lockText = (lock: Lock): string =>
  `${Formatter.formatJson(lock, { space: 2 })}\n`;
